/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-10: local coordination plugin (default) - a single instance is always
 *   the leader, claims are kept in memory
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

const PLUGIN_TYPE = "node-red-coordination";

/**
 * Validates the arguments of `claim()`.
 * @return {Error|null}
 */
function checkClaimArgs(key, ttlMs) {
    if (typeof key !== "string" || key.length === 0) {
        return new TypeError("claim key must be a non-empty string");
    }
    if (typeof ttlMs !== "number" || !isFinite(ttlMs) || ttlMs <= 0) {
        return new TypeError("claim ttlMs must be a positive number");
    }
    return null;
}

/**
 * Creates the local coordination plugin used when the `coordination.plugin`
 * setting is not set. The process is the only instance:
 *
 * - `isLeader()` is `true` from creation until `stop()` (and again after `start()`)
 * - `onLeaderChange` listeners are called only with `false` on `stop()`
 * - `claim(key, ttlMs)` keeps the claims in memory with the same semantics as
 *   a cluster plugin: the first claim of a key within its ttl gets a `Claim`,
 *   any later one gets `null`
 *
 * @return {CoordinationPlugin}
 */
function create() {
    // key -> {expiresAt}
    const claims = new Map();
    const listeners = new Set();
    let running = true;

    function removeExpired(now) {
        claims.forEach(function(entry, key) {
            if (entry.expiresAt <= now) {
                claims.delete(key);
            }
        });
    }

    const plugin = {
        id: "local",
        type: PLUGIN_TYPE,
        start: function(ctx) {
            running = true;
            return Promise.resolve();
        },
        stop: function() {
            const wasRunning = running;
            running = false;
            claims.clear();
            if (wasRunning) {
                listeners.forEach(function(listener) { listener(false) });
            }
            return Promise.resolve();
        },
        resign: function() {
            // There is no other instance to hand the leadership over to
            return Promise.resolve();
        },
        isLeader: function() {
            return running;
        },
        onLeaderChange: function(listener) {
            listeners.add(listener);
            return function() { listeners.delete(listener) };
        },
        claim: function(key, ttlMs) {
            const err = checkClaimArgs(key, ttlMs);
            if (err) {
                return Promise.reject(err);
            }
            if (!running) {
                return Promise.reject(new Error("local coordination is stopped"));
            }
            const now = Date.now();
            removeExpired(now);
            if (claims.has(key)) {
                return Promise.resolve(null);
            }
            const entry = {expiresAt: now + ttlMs};
            claims.set(key, entry);
            const claim = {
                key: key,
                expiresAt: entry.expiresAt,
                release: function() {
                    if (claims.get(key) === entry) {
                        claims.delete(key);
                    }
                    return Promise.resolve();
                },
                renew: function(renewTtlMs) {
                    const renewErr = checkClaimArgs(key, renewTtlMs);
                    if (renewErr) {
                        return Promise.reject(renewErr);
                    }
                    const renewNow = Date.now();
                    if (!running || claims.get(key) !== entry || entry.expiresAt <= renewNow) {
                        return Promise.resolve(false);
                    }
                    entry.expiresAt = renewNow + renewTtlMs;
                    claim.expiresAt = entry.expiresAt;
                    return Promise.resolve(true);
                }
            };
            return Promise.resolve(claim);
        },
        status: function() {
            return {connected: running};
        },
        // Number of the claims kept - for the tests
        _size: function() {
            return claims.size;
        }
    };
    return plugin;
}

module.exports = {
    create: create,
    checkClaimArgs: checkClaimArgs,
    PLUGIN_TYPE: PLUGIN_TYPE
};
